package algorithms.techniques;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class TwoPointers {
public static int[] twoSumSorted(double[] a,double t){int l=0,r=a.length-1;while(l<r){double s=a[l]+a[r];if(s==t)return new int[]{l,r};if(s<t)l++;else r--;}return null;}public static int[] twoSum(double[] a,double t){Map<Double,Integer> seen=new HashMap<>();for(int i=0;i<a.length;i++){Integer j=seen.get(t-a[i]);if(j!=null)return new int[]{j,i};seen.put(a[i],i);}return null;}public static List<double[]> threeSum(double[] values){return threeSum(values,0);}public static List<double[]> threeSum(double[] values,double target){List<Double> input=new ArrayList<>();for(double v:values)input.add(v);List<Double> a=algorithms.sorting.MergeSort.mergeSort(input);List<double[]> o=new ArrayList<>();for(int i=0;i<a.size()-2;i++){if(i>0&&a.get(i).equals(a.get(i-1)))continue;int l=i+1,r=a.size()-1;while(l<r){double s=a.get(i)+a.get(l)+a.get(r);if(s<target)l++;else if(s>target)r--;else{o.add(new double[]{a.get(i),a.get(l),a.get(r)});while(l<r&&a.get(l).equals(a.get(l+1)))l++;while(l<r&&a.get(r).equals(a.get(r-1)))r--;l++;r--;}}}return o;}public static double containerWithMostWater(double[] h){double b=0;for(int l=0,r=h.length-1;l<r;){b=Math.max(b,Math.min(h[l],h[r])*(r-l));if(h[l]<h[r])l++;else r--;}return b;}public static int removeDuplicatesSorted(List<Double> a){int w=0;for(int r=0;r<a.size();r++)if(r==0||!a.get(r).equals(a.get(w-1)))a.set(w++,a.get(r));a.subList(w,a.size()).clear();return w;}public static List<Double> dutchNationalFlag(List<Double> a,double pivot){int l=0,m=0,h=a.size()-1;while(m<=h){if(a.get(m)<pivot)Collections.swap(a,l++,m++);else if(a.get(m)>pivot)Collections.swap(a,m,h--);else m++;}return a;}public static <T> boolean hasCycleFloyd(T start,Function<T,T> next){T slow=start,fast=start;while(fast!=null){fast=next.apply(fast);if(fast==null)return false;fast=next.apply(fast);slow=next.apply(slow);if(fast!=null&&fast==slow)return true;}return false;}
}
